@import "@fontsource-variable/instrument-sans/standard.css";
@import "@fontsource/dm-mono/400.css";
@import "@fontsource/dm-mono/500.css";

/* Light (faithful for most of the page): white, ink text oklch(.2 .004 165), cards in the
   grey-teal 8% tint (#f5f8f8 on white), mint-teal #6af3d9 CTAs with ink text, hairlines in
   grey-teal (#81a5a9) at about 20%. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.2 0.0037 164.66);
  --card: oklch(0.977 0.0032 197.1);
  --card-foreground: oklch(0.2 0.0037 164.66);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2 0.0037 164.66);
  --primary: oklch(0.881 0.1257 178.8);
  --primary-foreground: oklch(0.165 0.0049 196.7);
  --secondary: oklch(0.942 0.0066 208.8);
  --secondary-foreground: oklch(0.2 0.0037 164.66);
  --muted: oklch(0.96 0.0045 200);
  --muted-foreground: oklch(0.53 0.0113 164.62);
  --accent: oklch(0.942 0.0066 208.8);
  --accent-foreground: oklch(0.2 0.0037 164.66);
  --destructive: oklch(0.6276 0.215 23.85);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.697 0.0398 204.7 / 24%);
  --input: oklch(0.697 0.0398 204.7 / 32%);
  --ring: oklch(0.6479 0.1212 174.82);
  --highlight: oklch(0.6479 0.1212 174.82);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.84 0.1608 173.06);
  --chart-1: oklch(0.84 0.1608 173.06);
  --chart-2: oklch(0.718 0.1077 247.2);
  --chart-3: oklch(0.6479 0.1212 174.82);
  --chart-4: oklch(0.7131 0.173 27.44);
  --chart-5: oklch(0.58 0.0113 164.62);
  --sidebar: oklch(0.977 0.0032 197.1);
  --sidebar-foreground: oklch(0.2 0.0037 164.66);
  --sidebar-primary: oklch(0.881 0.1257 178.8);
  --sidebar-primary-foreground: oklch(0.165 0.0049 196.7);
  --sidebar-accent: oklch(0.942 0.0066 208.8);
  --sidebar-accent-foreground: oklch(0.2 0.0037 164.66);
  --sidebar-border: oklch(0.697 0.0398 204.7 / 20%);
  --sidebar-ring: oklch(0.6479 0.1212 174.82);

  --typeface-body: "Instrument Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Instrument Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 78rem;
  --page-gutter: 1rem;
  --section-y: 5rem;

  /* Instrument Sans a touch narrower (its width axis), to match PP Neue Montreal's proportions */
  font-stretch: 94%;
}

/* Dark (faithful for the hero, fees, onboarding, safety and footer): #0f0f10 page, #181b1c
   cards (the same 8% grey-teal tint on black), off-white #f5f8f8 text, grey-teal #7f9195
   secondary text, the same mint. */
.dark {
  --background: oklch(0.169 0.0021 286.2);
  --foreground: oklch(0.977 0.0032 197.1);
  --card: oklch(0.219 0.005 219.7);
  --card-foreground: oklch(0.977 0.0032 197.1);
  --popover: oklch(0.219 0.005 219.7);
  --popover-foreground: oklch(0.977 0.0032 197.1);
  --primary: oklch(0.881 0.1257 178.8);
  --primary-foreground: oklch(0.165 0.0049 196.7);
  --secondary: oklch(0.977 0.0032 197.1);
  --secondary-foreground: oklch(0.165 0.0049 196.7);
  --muted: oklch(0.235 0.006 215);
  --muted-foreground: oklch(0.644 0.0215 212.6);
  --accent: oklch(0.26 0.0048 174.04);
  --accent-foreground: oklch(0.977 0.0032 197.1);
  --destructive: oklch(0.7131 0.173 27.44);
  --destructive-foreground: oklch(0.165 0.0049 196.7);
  --border: oklch(0.697 0.0398 204.7 / 16%);
  --input: oklch(0.697 0.0398 204.7 / 30%);
  --ring: oklch(0.881 0.1257 178.8);
  --highlight: oklch(0.881 0.1257 178.8);
  --highlight-foreground: oklch(0.165 0.0049 196.7);
  --glow: oklch(0.881 0.1257 178.8);
  --chart-1: oklch(0.881 0.1257 178.8);
  --chart-2: oklch(0.718 0.1077 247.2);
  --chart-3: oklch(0.6479 0.1212 174.82);
  --chart-4: oklch(0.7131 0.173 27.44);
  --chart-5: oklch(0.731 0.0014 106.4);
  --sidebar: oklch(0.219 0.005 219.7);
  --sidebar-foreground: oklch(0.977 0.0032 197.1);
  --sidebar-primary: oklch(0.881 0.1257 178.8);
  --sidebar-primary-foreground: oklch(0.165 0.0049 196.7);
  --sidebar-accent: oklch(0.26 0.0048 174.04);
  --sidebar-accent-foreground: oklch(0.977 0.0032 197.1);
  --sidebar-border: oklch(0.697 0.0398 204.7 / 16%);
  --sidebar-ring: oklch(0.881 0.1257 178.8);
}
